from pathlib import Path
import json,base64,hashlib
R=Path(__file__).parent;S=json.loads((R/'story.json').read_text());A=R.parent/'Part04_FINAL_VOICEOVER.mp3'
assert hashlib.sha256(A.read_bytes()).hexdigest()==S['timeline']['audio_sha256'],'Wrong master audio'
assert S['timeline']['audio_track_count']==1 and not S['timeline']['audio_edits']
keys={e['key'] for s in S['slides'] for e in s['elements'] if e['type'] in ['image','crop']}
assets={k:'data:image/png;base64,'+base64.b64encode((R/'assets'/f'{k}.png').read_bytes()).decode() for k in keys}
style=(R/'player.css').read_text().replace('MANROPE_DATA',base64.b64encode((R/'assets/manrope.woff2').read_bytes()).decode()).replace('ARABIC_DATA',base64.b64encode((R/'assets/arabic.woff2').read_bytes()).decode())
js=(R/'player.js').read_text();audio=base64.b64encode(A.read_bytes()).decode()
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GRINDCTRL × Concrete — Part 04: AI opportunities</title><style>'''+style+'''</style></head><body><header><div class="identity"><img id="brand" alt=""><bdi>GRINDCTRL × Concrete</bdi></div><div class="header-actions"><button data-action="language">العربية</button><button data-action="zoom" aria-pressed="false">Enlarge scene</button><button data-action="notes">Evidence notes</button><button data-action="print">PDF</button></div></header><main><div id="deck" tabindex="0" aria-label="Part 04 presentation"></div><div class="controls"><button id="play" class="primary" data-action="play">Play narration</button><button data-action="replay">Replay</button><button data-action="step">Next phrase</button><button data-action="mute" aria-pressed="false">Mute</button><span id="time" class="time">0:00</span><label class="seek-label" for="seek">Narration position</label><input id="seek" type="range" min="0" max="'''+str(S['timeline']['duration'])+'''" step="0.01" value="0" aria-label="Narration position"></div><nav id="chapters" aria-label="Nine visual topics"></nav><div class="caption-row"><button id="caption-toggle" data-action="captions" aria-pressed="false">Arabic captions</button><span>ONE continuous final MP3 · Proposed experiences · English / RTL layout</span></div><div id="caption" dir="rtl" hidden></div></main><audio id="audio" preload="auto" src="data:audio/mpeg;base64,'''+audio+'''"></audio><dialog id="notes"><div id="note-content"></div><button data-action="close">Close</button></dialog><div class="sr-only" id="announce" aria-live="polite"></div><script>const story='''+json.dumps(S,ensure_ascii=False).replace('</','<\\/')+''';const assets='''+json.dumps(assets)+''';</script><script>'''+js+'''</script></body></html>'''
(R.parent/'GRINDCTRL_Concrete_Part04_AI_Opportunities.html').write_text(html)
print('Self-contained HTML; ONE unchanged master MP3; cropped illustrative reference imagery and native editable UI.')
